class Unit{
constructor(g,team,lane,x,z){this.g=g;this.team=team;this.lane=lane;this.position=new THREE.Vector3(x,0,z);this.dead=false;this.hp=1;this.maxHp=1;this.group=null;}
bar(){if(!this.hpFill)return;const r=clamp(this.hp/this.maxHp,0,1);this.hpFill.scale.x=Math.max(.001,r);this.hpFill.position.x=-(1-r)*this.barW/2;if(this.hpBar)this.hpBar.quaternion.copy(this.g.camera.quaternion);}
takeDamage(n,s,type){if(this.dead||s&&s.team===this.team)return;this.hp-=Math.max(1,n);this.g.number(this.position,Math.round(n),type||'physical');this.g.hit(this.position,type==='magic'?0x9b8dff:0xffdf9c);if(this.hp<=0)this.die(s);this.bar();}
die(s){if(this.dead)return;this.dead=true;if(this.group)this.g.scene.remove(this.group);if(s&&s.gain)s.gain(this.gold||0,this.exp||0);}
}
class Tower extends Unit{
constructor(g,t,l,tier,x,z,core){super(g,t,l,x,z);this.tier=tier;this.core=core;this.maxHp=core?9200:[1700,2350,3100][tier];this.hp=this.maxHp;this.range=core?15:12.8;this.damage=core?210:145+tier*25;this.cool=1;this.gold=0;this.exp=0;this.model();}
model(){const g=new THREE.Group();this.group=g;g.position.copy(this.position);const c=tc(this.team),stone=mat(this.team==='blue'?0x3c5660:0x63464d,{metalness:.25,roughness:.65}),trim=mat(0xd1b77c,{metalness:.58,roughness:.28}),roof=mat(this.team==='blue'?0x3c8b9a:0xa34c57,{metalness:.38,roughness:.3}),glow=mat(c,{metalness:.35,roughness:.2,emissive:c,emissiveIntensity:.9});const scale=this.core?1.35:1;add(new THREE.CylinderGeometry(1.4*scale,1.72*scale,.42,12),stone,g,0,.22,0);add(new THREE.CylinderGeometry(1.28*scale,1.45*scale,.14,12),trim,g,0,.49,0);add(new THREE.TorusGeometry(1.25*scale,.07,7,32),glow,g,0,.59,0).rotation.x=Math.PI/2;add(new THREE.CylinderGeometry(.74*scale,.96*scale,1.25*scale,10),stone,g,0,1.22*scale,0);add(new THREE.CylinderGeometry(.9*scale,.96*scale,.14,10),trim,g,0,1.88*scale,0);add(new THREE.ConeGeometry(1.18*scale,.48*scale,8),roof,g,0,2.18*scale,0);add(new THREE.CylinderGeometry(.1*scale,.16*scale,.42*scale,8),trim,g,0,2.56*scale,0);if(this.core){add(new THREE.OctahedronGeometry(1.12,1),glow,g,0,3.35,0,1,1.25,1);add(new THREE.OctahedronGeometry(.54,1),trim,g,0,3.35,0,.62,1.25,.62);const halo=add(new THREE.TorusGeometry(1.55,.065,7,36),glow,g,0,3.2,0);halo.rotation.x=Math.PI/2;const h2=add(new THREE.TorusGeometry(1.88,.035,5,36),trim,g,0,3.2,0);h2.rotation.x=Math.PI/2;this.spinParts=[halo,h2];}else{add(new THREE.OctahedronGeometry(.58,1),glow,g,0,2.9,0,1,1.25,1);const h=add(new THREE.TorusGeometry(.82,.05,6,28),trim,g,0,2.88,0);h.rotation.x=Math.PI/2;this.spinParts=[h];for(let i=0;i<4;i++){const a=i*Math.PI/2+Math.PI/4,px=Math.cos(a)*1.08,pz=Math.sin(a)*1.08;add(new THREE.CylinderGeometry(.12,.2,.82,7),trim,g,px,1.05*scale,pz);add(new THREE.OctahedronGeometry(.16),glow,g,px,1.55*scale,pz);}}this.barW=this.core?3.8:2.5;this.hpBar=new THREE.Group();this.hpBar.position.y=this.core?5.2:4.1;add(new THREE.PlaneGeometry(this.barW,.25),flat(0x08141b,.92),this.hpBar);this.hpFill=add(new THREE.PlaneGeometry(this.barW-.06,.17),flat(this.team==='blue'?0x4acb9b:0xff626e),this.hpBar,0,0,.012);g.add(this.hpBar);g.scale.setScalar(this.core?1.12:1.05);this.g.scene.add(g);this.bar();}

takeDamage(n,s,type){if(this.dead)return;if(this.core&&!this.g.coreOpen(this.team)){this.g.toast('敌方水晶仍受高地防御保护');return;}super.takeDamage(n,s,type);if(this.dead)this.g.towerDown(this,s);}
update(dt){if(this.dead)return;this.cool-=dt;let t=this.g.minions.filter(m=>ok(m)&&m.team!==this.team&&dist(m.position,this.position)<this.range).sort((a,b)=>dist(a.position,this.position)-dist(b.position,this.position))[0];if(!t)t=this.g.heroes.filter(h=>ok(h)&&h.team!==this.team&&dist(h.position,this.position)<this.range).sort((a,b)=>dist(a.position,this.position)-dist(b.position,this.position))[0];if(t&&this.cool<=0){this.cool=1.05;this.g.project(this.position.clone().add(new THREE.Vector3(0,this.core?2.7:3.5,0)),t,this.damage,tc(this.team),'physical',16,this);}if(this.spinParts)this.spinParts.forEach((o,i)=>{o.rotation.y+=dt*(i%2?.7:-.5);o.rotation.z+=dt*.35;});this.bar();}
}
