update(dt){if(this.dead){this.respawn-=dt;if(this.respawn<=0){this.dead=false;this.hp=this.maxHp;this.position.copy(this.home);this.group.position.copy(this.home);this.g.scene.add(this.group);this.target=null;}return;}this.cool=Math.max(0,this.cool-dt);const near=this.g.heroes.filter(h=>ok(h)&&dist(h.position,this.position)<this.aggro);if(!ok(this.target)||!this.target||dist(this.target.position,this.home)>this.aggro*1.8)this.target=near[0]||null;if(ok(this.target)){const d=dist(this.position,this.target.position);if(d>2.3){const v=this.target.position.clone().sub(this.position);v.y=0;v.normalize();this.position.addScaledVector(v,2.7*dt);}else if(this.cool<=0){this.cool=1.55;this.target.takeDamage(this.damage,this,'physical');}}else this.position.lerp(this.home,Math.min(1,dt*1.6));this.group.position.copy(this.position);this.group.rotation.y+=dt*.2;this.bar();}
