const jade=new THREE.MeshStandardMaterial({color:0x1c3935,roughness:.94}),stone=new THREE.MeshStandardMaterial({color:0x33463e,roughness:.9}),darkStone=new THREE.MeshStandardMaterial({color:0x20332f,roughness:.96}),gold=new THREE.MeshStandardMaterial({color:0xd3b66e,metalness:.62,roughness:.3}),red=new THREE.MeshStandardMaterial({color:0x763b35,roughness:.7}),glow=new THREE.MeshStandardMaterial({color:0x70cfc0,emissive:0x1d796c,emissiveIntensity:1.2,metalness:.25,roughness:.3});
const floor=mesh(new THREE.PlaneGeometry(70,70),jade,0,-.55,-8);floor.rotation.x=-Math.PI/2;
