mesh(new THREE.BoxGeometry(7.4,.48,.8),red,0,5.05,0,gate);mesh(new THREE.BoxGeometry(7.7,.13,1.02),gold,0,5.34,0,gate);
const roof1=mesh(new THREE.BoxGeometry(9.1,.25,1.8),darkStone,0,5.63,0,gate);roof1.rotation.z=.025;
