for(const side of [-1,1]){const column=mesh(new THREE.BoxGeometry(.2,4.4,.2),gold,side*5.1,2.1,-1.1);const cap=mesh(new THREE.BoxGeometry(.55,.24,.55),red,side*5.1,4.36,-1.1);mesh(new THREE.ConeGeometry(.43,.35,4),gold,side*5.1,4.62,-1.1);}
const banner=mesh(new THREE.PlaneGeometry(.9,2.2),red,stageX-4.2,3.1,-4.9);banner.rotation.y=-.1;
const banner2=mesh(new THREE.PlaneGeometry(.9,2.2),red,stageX+4.2,3.1,-4.9);banner2.rotation.y=.1;
for(const [x,z,sc] of [[-6,-4,1.3],[7,-6,1.7],[-8,-10,2],[10,-12,1.6],[-4,-14,1.1],[5,-15,1.2]]){const tree=new THREE.Group();tree.position.set(x,-.4,z);this.lobbyScene.add(tree);mesh(new THREE.CylinderGeometry(.16,.26,1.8,7),new THREE.MeshStandardMaterial({color:0x4b3d2c}),0,.9,0,tree);for(let j=0;j<3;j++)mesh(new THREE.IcosahedronGeometry(.95-j*.1,1),new THREE.MeshStandardMaterial({color:j===0?0x244f3e:0x326449,roughness:1}),0,1.7+j*.58,0,tree);}
