makeTowers(){for(const l of LANES)for(const team of ['blue','red'])for(let tier=0;tier<3;tier++){const x=team==='blue'?-16-tier*13:16+tier*13;this.towers.push(new Tower(this,team,l.id,tier,x,laneZ(l.id,x),false));}this.towers.push(new Tower(this,'blue',1,3,-54,33,true),new Tower(this,'red',1,3,54,-33,true));}

cards(){const root=document.getElementById('hero-list');root.innerHTML=Object.values(HEROES).map((h,i)=>'<button class="hero-card" data-hero="'+h.id+'" style="--hero-glow:'+new THREE.Color(h.glow).getStyle()+';--hero-color:'+new THREE.Color(h.main).getStyle()+'"><div class="hero-art"><span class="hero-num">0'+(i+1)+'</span><span class="hero-glyph">'+h.glyph+'</span><span class="hero-class">'+h.role.split(' · ')[0]+'</span></div><div class="hero-card-copy"><strong>'+h.name+'</strong><small>'+h.tag+'</small><div class="hero-card-footer"><span>'+h.role.split(' · ')[1]+'</span><span class="hero-dots"><i></i><i></i><i></i></span></div></div></button>').join('');root.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>this.select(b.dataset.hero));}
select(id){this.choice=id;const h=HEROES[id];document.querySelectorAll('.hero-card').forEach(b=>b.classList.toggle('active',b.dataset.hero===id));const setText=(key,value)=>{const e=document.getElementById(key);if(e)e.textContent=value;};setText('selected-emblem',h.glyph);const emblem=document.getElementById('selected-emblem');if(emblem)emblem.style.color=new THREE.Color(h.glow).getStyle();setText('selected-role',h.role);setText('selected-name',h.name);setText('selected-tagline',h.tag);setText('lobby-hero-name',h.name);setText('lobby-hero-tagline',h.tag);setText('lobby-hero-role',h.role);['hp','dmg','mob'].forEach((k,i)=>{const e=document.getElementById('stat-'+k);if(e)e.style.width=h.stats[i]+'%';});const skills=document.getElementById('selected-skills');if(skills)skills.innerHTML=h.skills.map((v,i)=>'<div class="preview-skill"><span>'+h.icons[i]+'</span><b>'+v+'</b></div>').join('');if(!this.started&&this.lobbyScene)this.setPreviewHero(id);}
