ai(h){h.move.set(0,0,0);if(h.hp/h.maxHp<.23){h.order=false;h.target=null;const x=h.team==='blue'?-52:52,z=laneZ(h.lane,x);if(Math.hypot(x-h.position.x,z-h.position.z)>4)h.move.set(x-h.position.x,0,z-h.position.z).normalize();else{h.hp=Math.min(h.maxHp,h.hp+this.dt*h.maxHp*.12);h.mana=Math.min(h.maxMana,h.mana+this.dt*h.maxMana*.16);}return;}let t=this.nearest(h,8.5);if(!t){const a=this.minions.filter(m=>ok(m)&&m.team!==h.team&&m.lane===h.lane&&Math.abs(m.position.z-h.position.z)<5&&dist(m.position,h.position)<8).sort((x,y)=>dist(x.position,h.position)-dist(y.position,h.position));t=a[0]||null;}if(!t)t=this.nextTower(h.team,h.lane);h.target=t;h.order=!!t;if(t){const d=dist(h.position,t.position);if(d>h.range*.86)h.move.copy(t.position).sub(h.position).setY(0).normalize();else{if(h.cooldowns[0]<=0&&d<12)h.skill(0);if(h.cooldowns[1]<=0&&d<8)h.skill(1);if(h.cooldowns[2]<=0&&d<7&&(!t.hp||t.hp/t.maxHp<.58))h.skill(2);}}}
spawnWave(){if(!this.started)return;this.wave++;for(const l of LANES)for(const t of ['blue','red']){const dir=t==='blue'?1:-1,x0=t==='blue'?-52:52;for(let i=0;i<3;i++){const x=x0-dir*i*1.15;this.minions.push(new Minion(this,t,l.id,'melee',x,laneZ(l.id,x)));}for(let i=0;i<2;i++){const x=x0-dir*(3.8+i*1.15);this.minions.push(new Minion(this,t,l.id,'ranged',x,laneZ(l.id,x)));}if(this.wave%3===0){const x=x0-dir*6.6;this.minions.push(new Minion(this,t,l.id,'siege',x,laneZ(l.id,x)));}}if(this.minions.length>90)this.minions.splice(0,this.minions.length-90);}

heroDown(k,v){if(k.team==='blue')this.blueKills++;else this.redKills++;document.getElementById('blue-score').textContent=this.blueKills;document.getElementById('red-score').textContent=this.redKills;const f=document.getElementById('kill-feed'),e=document.createElement('div');e.className='kill-item';e.innerHTML='<b>'+k.name+'</b> 击败 <span class="enemy">'+v.name+'</span>';f.prepend(e);while(f.children.length>4)f.lastElementChild.remove();setTimeout(()=>e.remove(),5200);}
