updateFx(dt){for(let i=this.projectiles.length-1;i>=0;i--){const p=this.projectiles[i];p.life-=dt;if(p.life<=0||!ok(p.target)){this.scene.remove(p.g);this.projectiles.splice(i,1);continue;}const end=p.target.position.clone();end.y+=p.target instanceof Hero?2:p.target instanceof Tower?2.2:1.1;if(p.spread){end.z+=p.spread*7;end.x+=p.spread*3;}const v=end.sub(p.g.position),d=v.length();if(d<p.speed*dt+.35){p.target.takeDamage(p.n,p.source||this.player||{team:enemy(p.target.team)},p.type);if(p.onHit)p.onHit(p.target);this.hit(p.target.position,p.color);this.scene.remove(p.g);this.projectiles.splice(i,1);}else{v.normalize();p.g.position.addScaledVector(v,p.speed*dt);}}for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.life-=dt;const t=1-clamp(e.life/e.max,0,1);if(e.g){e.g.scale.setScalar(1+t*.34);e.ring.material.opacity=.8*(1-t);e.fill.material.opacity=.12*(1-t);}else{e.m.scale.setScalar(1+t*.6);e.m.material.opacity=.82*(1-t);}if(e.life<=0){this.scene.remove(e.g||e.m);this.effects.splice(i,1);}}for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;p.m.position.addScaledVector(p.v,dt);p.v.y-=7*dt;p.m.scale.multiplyScalar(.985);if(p.life<=0){this.scene.remove(p.m);this.particles.splice(i,1);}}}
ui(){if(!this.player)return;const h=this.player;document.getElementById('match-clock').textContent=String(Math.floor(this.time/60)).padStart(2,'0')+':'+String(Math.floor(this.time%60)).padStart(2,'0');document.getElementById('player-gold').textContent=Math.floor(h.gold);document.getElementById('player-name').textContent=h.name;document.getElementById('player-level').textContent=h.level;document.getElementById('player-kda').textContent=h.kills+' / '+h.deaths+' / 0';document.getElementById('player-portrait').textContent=h.glyph;document.getElementById('player-hp-fill').style.width=clamp(h.hp/h.maxHp*100,0,100)+'%';document.getElementById('player-mana-fill').style.width=clamp(h.mana/h.maxMana*100,0,100)+'%';document.getElementById('player-exp-fill').style.width=clamp(h.exp/h.nextExp*100,0,100)+'%';h.d.skills.forEach((n,i)=>{document.getElementById('skill-name-'+(i+1)).textContent=n;const m=document.getElementById('skill-mask-'+(i+1)),cd=h.cooldowns[i];m.classList.toggle('active',cd>0);m.textContent=cd>0?Math.ceil(cd):'';});[['recall-mask',h.recall?h.recallTimer:0],['heal-mask',h.healCd],['flash-mask',h.flashCd]].forEach(a=>{const m=document.getElementById(a[0]);m.classList.toggle('active',a[1]>0);m.textContent=a[1]>0?Math.ceil(a[1]):'';});if(h.recall)document.getElementById('recall-progress-fill').style.width=clamp((4-h.recallTimer)/4*100,0,100)+'%';const n=this.towers.filter(t=>!t.dead&&t.team==='red'&&!t.core).length;document.getElementById('objective-text').textContent=this.coreOpen('red')?'突破高地，摧毁水晶':n===0?'推进其他路线':'沿中路推进';document.getElementById('objective-sub').textContent=this.coreOpen('red')?'敌方核心已暴露':n+' 座敌方防御塔仍在守卫';this.map();}
map(){const c=document.getElementById('minimap'),x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);x.fillStyle='#183c32';x.fillRect(0,0,w,h);const xy=p=>[(p.x+65)/130*w,(p.z+43)/86*h];x.save();x.lineCap='round';for(const l of LANES){const a=xy({x:-58,z:laneZ(l.id,-58)}),b=xy({x:58,z:laneZ(l.id,58)});x.strokeStyle='#536b60';x.lineWidth=9;x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(b[0],b[1]);x.stroke();x.strokeStyle='#8a9278';x.lineWidth=1.3;x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(b[0],b[1]);x.stroke();}x.strokeStyle='#287a8a';x.lineWidth=8;x.beginPath();x.moveTo(...xy({x:-25,z:-41}));x.lineTo(...xy({x:25,z:41}));x.stroke();for(const p0 of [[-54,33],[54,-33]]){const p=xy({x:p0[0],z:p0[1]});x.fillStyle='#4ca6b8';x.beginPath();x.arc(p[0],p[1],6,0,Math.PI*2);x.fill();}for(const t of this.towers.filter(ok)){const p=xy(t.position);x.fillStyle=t.team==='blue'?'#58bdff':'#ff6f7c';x.fillRect(p[0]-2.2,p[1]-2.2,4.4,4.4);}for(const m of this.minions.filter(ok)){const p=xy(m.position);x.fillStyle=m.team==='blue'?'#73d5ff':'#ff969a';x.fillRect(p[0]-1,p[1]-1,2,2);}for(const h of this.heroes.filter(ok)){const p=xy(h.position);x.beginPath();x.fillStyle=h===this.player?'#fff0a5':h.team==='blue'?'#54baff':'#ff707c';x.arc(p[0],p[1],h===this.player?4:2.5,0,Math.PI*2);x.fill();}x.restore();}

shop(){if(!this.started||this.paused||this.over)return;document.getElementById('shop-modal').classList.remove('hidden');this.renderShop();}
renderShop(){document.getElementById('shop-gold').textContent=Math.floor(this.player.gold);document.getElementById('shop-items').innerHTML=ITEMS.map(it=>'<article class="shop-item"><span class="shop-item-icon">'+it.icon+'</span><strong>'+it.name+'</strong><p>'+it.desc+'</p><footer><b>◈ '+it.cost+'</b><button data-buy="'+it.id+'" '+(this.player.gold<it.cost?'disabled':'')+'>购买</button></footer></article>').join('');}
buy(id){const it=ITEMS.find(x=>x.id===id),h=this.player;if(!it||!h||h.dead)return;if(h.gold<it.cost){this.toast('金币不足');return;}if(h.items.length>=6){this.toast('装备栏已满');return;}h.gold-=it.cost;h.items.push(id);const e=it.effect;if(e.atk)h.atk+=e.atk;if(e.magic)h.magic+=e.magic;if(e.armor)h.armor+=e.armor;if(e.hp){h.maxHp+=e.hp;h.hp+=e.hp;}if(e.mana){h.maxMana+=e.mana;h.mana+=e.mana;}if(e.speed)h.speed+=e.speed;if(e.lifesteal)h.lifesteal+=e.lifesteal;if(e.crit)h.crit+=e.crit;h.bar();this.renderShop();this.toast('已购买：'+it.name);}
pause(){if(!this.started||this.over)return;this.paused=true;document.getElementById('pause-modal').classList.remove('hidden');}
resume(){this.paused=false;document.getElementById('pause-modal').classList.add('hidden');this.last=performance.now();}
